rule.definition:
a!localVariables(
  local!queryDataSubset:#"SYSTEM_SYSRULES_queryEntity_v1"(
    entity: #"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3461731",
    fetchtotalcount: ri!fetchTotalCount,
    query: #"SYSTEM_SYSRULES_query"(
      selection: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!columns),
        {},
        #"SYSTEM_SYSRULES_querySelection"(
          columns: #"SYSTEM_SYSRULES_forEach"(
            items: ri!columns,
            expression: #"SYSTEM_SYSRULES_queryColumn"(field: fv!item)
          )
        )
      ),
      logicalexpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        ignorefilterswithemptyvalues: true,
        operator: "AND",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "askID",
            operator: "in",
            value: ri!asks
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "statusId",
            operator: "<>",
            value: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3891969"
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "isActive",
            operator: "=",
            value: true
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "fiscalYear",
            operator: "=",
            value: ri!fiscalYear
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "positionTypeId",
            operator: "=",
            value: ri!posititionTypeId
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "subPositionTypeId",
            operator: "in",
            value: ri!subPositionTypeId
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "askID",
            operator: "not null"
          )
        }
      ),
      paginginfo: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!pagingInfo),
        #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: -1,
          sort: {
            #"SYSTEM_SYSRULES_sortInfo"(
              field: "nominationId",
              ascending: false
            )
          },
        ),
        ri!pagingInfo
      )
    )

  ),
  if(
    ri!returnCDT,
    cast(
      'type!{urn:com:appian:types:CAW}CAW_Nomination?list',
      local!queryDataSubset.data
    ),
    local!queryDataSubset
  )
)
